select date_trunc('month', end_date) as activity_month, date_trunc('week', start_date) as week_start, count(case when status = 'CANCELLED' then 1 end) as cancelled_count, approx_percentile(monthly_fee, 0.95) as monthly_fee_p95, sum(monthly_fee) filter (where status = 'CANCELLED') as cancelled_total_monthly_fee, stddev_samp(monthly_fee) as monthly_fee_stddev, percent_rank() over (partition by date_trunc('month', end_date) order by sum(monthly_fee) filter (where status = 'CANCELLED') desc) as cancelled_total_monthly_fee_percent_rank from subscriptions group by date_trunc('month', end_date), date_trunc('week', start_date) order by cancelled_count desc;
